export const HOCCHAN_SNAPSHOT_FILES: readonly HocchanSnapshotFile[] = RAW_SNAPSHOT.map(
  ([accountIndex, virtualPath, sizeBytes, mimeType, updatedAt]) => {
    const slashIndex = virtualPath.lastIndexOf('/');
    return {
      accountIndex,
      virtualPath,
      name: slashIndex >= 0 ? virtualPath.slice(slashIndex + 1) : virtualPath,
      sizeBytes,
      mimeType,
      updatedAt,
    };
  }
);
